module buffalo_bill_solver (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [2:0] num_snakes,\n    input wire [9:0] snake_x0,\n    input wire [9:0] snake_y0,\n    input wire [9:0] snake_d0,\n    input wire [9:0] snake_x1,\n    input wire [9:0] snake_y1,\n    input wire [9:0] snake_d1,\n    input wire [9:0] snake_x2,\n    input wire [9:0] snake_y2,\n    input wire [9:0] snake_d2,\n    input wire [9:0] snake_x3,\n    input wire [9:0] snake_y3,\n    input wire [9:0] snake_d3,\n    output reg path_found,\n    output reg [6:0] entry_y_step,\n    output reg [6:0] exit_y_step,\n    output reg done\n);\n\n    // Parameters\n    localparam [3:0] STEP = 10;\n    localparam [6:0] MAX_Y_STEP = 100;\n    localparam [9:0] FIELD_SIZE = 1000;\n\n    // Internal registers\n    reg [2:0] state;\n    reg [9:0] snake_x_reg [0:3];\n    reg [9:0] snake_y_reg [0:3];\n    reg [9:0] snake_d_reg [0:3];\n    reg [2:0] num_snakes_reg;\n    reg [6:0] y_step;\n    reg found_entry, found_exit;\n\n    // State definitions\n    localparam [2:0] IDLE = 3'd0;\n    localparam [2:0] BARRIER_COMPUTE = 3'd1;\n    localparam [2:0] LEFT_START = 3'd2;\n    localparam [2:0] LEFT_LOOP = 3'd3;\n    localparam [2:0] RIGHT_START = 3'd4;\n    localparam [2:0] RIGHT_LOOP = 3'd5;\n    localparam [2:0] DONE = 3'd6;\n\n    // Combinational barrier computation\n    wire barrier_exists_comb;\n\n    // Combinational safety checks\n    wire is_safe_left_comb;\n    wire is_safe_right_comb;\n\n    // Function to compute barrier\n    function automatic logic compute_barrier;\n        logic [1:0] parent [0:3];\n        logic touch_top [0:3];\n        logic touch_bottom [0:3];\n        logic barrier;\n        integer i, j, root;\n        logic [19:0] dx, dy, dx2, dy2, dist_sq;\n        logic [19:0] rad_sum, rad_sum_sq;\n        begin\n            for (i=0; i<4; i=i+1) begin\n                parent[i] = i[1:0];\n                if (i < num_snakes_reg) begin\n                    touch_top[i] = (snake_y_reg[i] + snake_d_reg[i] >= FIELD_SIZE);\n                    touch_bottom[i] = (snake_y_reg[i] <= snake_d_reg[i]);\n                end else begin\n                    touch_top[i] = 1'b0;\n                    touch_bottom[i] = 1'b0;\n                end\n            end\n\n            for (i=0; i<4; i=i+1) begin\n                for (j=i+1; j<4; j=j+1) begin\n                    if (i < num_snakes_reg && j < num_snakes_reg) begin\n                        dx = (snake_x_reg[i] > snake_x_reg[j]) ? (snake_x_reg[i] - snake_x_reg[j]) : \n                                                           (snake_x_reg[j] - snake_x_reg[i]);\n                        dy = (snake_y_reg[i] > snake_y_reg[j]) ? (snake_y_reg[i] - snake_y_reg[j]) : \n                                                           (snake_y_reg[j] - snake_y_reg[i]);\n                        dx2 = dx * dx;\n                        dy2 = dy * dy;\n                        dist_sq = dx2 + dy2;\n                        rad_sum = snake_d_reg[i] + snake_d_reg[j];\n                        rad_sum_sq = rad_sum * rad_sum;\n                        if (dist_sq < rad_sum_sq) begin\n                            parent[j] = parent[i];\n                        end\n                    end\n                end\n            end\n\n            barrier = 1'b0;\n            for (i=0; i<4; i=i+1) begin\n                if (i < num_snakes_reg) begin\n                    root = i;\n                    while (parent[root] != root) begin\n                        root = parent[root];\n                    end\n                    if (touch_top[root] && touch_bottom[root]) begin\n                        barrier = 1'b1;\n                    end\n                end\n            end\n            compute_barrier = barrier;\n        end\n    endfunction\n\n    // Left safety check\n    function automatic logic compute_left_safe;\n        logic safe;\n        integer i;\n        logic [19:0] dx, dy, dx2, dy2, dist_sq;\n        logic [19:0] rad_sq;\n        logic [16:0] py;\n        begin\n            safe = 1'b1;\n            py = y_step * STEP;\n            for (i=0; i<4; i=i+1) begin\n                if (i < num_snakes_reg) begin\n                    dx = (10'd0 > snake_x_reg[i]) ? (10'd0 - snake_x_reg[i]) : (snake_x_reg[i] - 10'd0);\n                    dy = (py > snake_y_reg[i]) ? (py - snake_y_reg[i]) : (snake_y_reg[i] - py);\n                    dx2 = dx * dx;\n                    dy2 = dy * dy;\n                    dist_sq = dx2 + dy2;\n                    rad_sq = snake_d_reg[i] * snake_d_reg[i];\n                    if (dist_sq < rad_sq) begin\n                        safe = 1'b0;\n                    end\n                end\n            end\n            compute_left_safe = safe;\n        end\n    endfunction\n\n    // Right safety check\n    function automatic logic compute_right_safe;\n        logic safe;\n        integer i;\n        logic [19:0] dx, dy, dx2, dy2, dist_sq;\n        logic [19:0] rad_sq;\n        logic [16:0] py;\n        begin\n            safe = 1'b1;\n            py = y_step * STEP;\n            for (i=0; i<4; i=i+1) begin\n                if (i < num_snakes_reg) begin\n                    dx = (FIELD_SIZE > snake_x_reg[i]) ? (FIELD_SIZE - snake_x_reg[i]) : \n                                                       (snake_x_reg[i] - FIELD_SIZE);\n                    dy = (py > snake_y_reg[i]) ? (py - snake_y_reg[i]) : (snake_y_reg[i] - py);\n                    dx2 = dx * dx;\n                    dy2 = dy * dy;\n                    dist_sq = dx2 + dy2;\n                    rad_sq = snake_d_reg[i] * snake_d_reg[i];\n                    if (dist_sq < rad_sq) begin\n                        safe = 1'b0;\n                    end\n                end\n            end\n            compute_right_safe = safe;\n        end\n    endfunction\n\n    assign barrier_exists_comb = compute_barrier();\n    assign is_safe_left_comb = compute_left_safe();\n    assign is_safe_right_comb = compute_right_safe();\n\n    // Main state machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            path_found <= 1'b0;\n            entry_y_step <= 7'd0;\n            exit_y_step <= 7'd0;\n            done <= 1'b0;\n            num_snakes_reg <= 3'd0;\n            y_step <= 7'd0;\n            found_entry <= 1'b0;\n            found_exit <= 1'b0;\n\n            // Initialize arrays\n            for (integer k = 0; k < 4; k = k + 1) begin\n                snake_x_reg[k] <= 10'd0;\n                snake_y_reg[k] <= 10'd0;\n                snake_d_reg[k] <= 10'd0;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        snake_x_reg[0] <= snake_x0;\n                        snake_x_reg[1] <= snake_x1;\n                        snake_x_reg[2] <= snake_x2;\n                        snake_x_reg[3] <= snake_x3;\n\n                        snake_y_reg[0] <= snake_y0;\n                        snake_y_reg[1] <= snake_y1;\n                        snake_y_reg[2] <= snake_y2;\n                        snake_y_reg[3] <= snake_y3;\n\n                        snake_d_reg[0] <= snake_d0;\n                        snake_d_reg[1] <= snake_d1;\n                        snake_d_reg[2] <= snake_d2;\n                        snake_d_reg[3] <= snake_d3;\n\n                        num_snakes_reg <= num_snakes;\n                        state <= BARRIER_COMPUTE;\n                    end\n                end\n\n                BARRIER_COMPUTE: begin\n                    if (barrier_exists_comb) begin\n                        path_found <= 1'b0;\n                        state <= DONE;\n                    end else begin\n                        state <= LEFT_START;\n                    end\n                end\n\n                LEFT_START: begin\n                    y_step <= MAX_Y_STEP;\n                    found_entry <= 1'b0;\n                    state <= LEFT_LOOP;\n                end\n\n                LEFT_LOOP: begin\n                    if (y_step <= 7'd100 && !found_entry) begin\n                        if (is_safe_left_comb) begin\n                            entry_y_step <= y_step;\n                            found_entry <= 1'b1;\n                            state <= RIGHT_START;\n                        end else begin\n                            y_step <= y_step - 7'd1;\n                        end\n                    end else begin\n                        if (!found_entry) begin\n                            path_found <= 1'b0;\n                            state <= DONE;\n                        end\n                    end\n                end\n\n                RIGHT_START: begin\n                    y_step <= MAX_Y_STEP;\n                    found_exit <= 1'b0;\n                    state <= RIGHT_LOOP;\n                end\n\n                RIGHT_LOOP: begin\n                    if (y_step <= 7'd100 && !found_exit) begin\n                        if (is_safe_right_comb) begin\n                            exit_y_step <= y_step;\n                            found_exit <= 1'b1;\n                            state <= DONE;\n                            path_found <= 1'b1;\n                        end else begin\n                            y_step <= y_step - 7'd1;\n                        end\n                    end else begin\n                        if (!found_exit) begin\n                            path_found <= 1'b0;\n                            state <= DONE;\n                        end\n                    end\n                end\n\n                DONE: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule\n